responseSchemaJson:
{
  "type": "object",
  "description": "Core data structure for 'Drawing Master'. Generates structured English tags based on the character's state.",
  "properties": {
    "data": {
      "type": "object",
      "description": "[Module 1: Drawing Data Generation] Define environment and character-specific metadata.",
      "properties": {
        "global": {
          "type": "object",
          "description": "Scene-wide settings and the core shared interaction concept.",
          "properties": {
            "time": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Time of day or lighting condition tags."
            },
            "locationAndBackground": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Environment or background description tags."
            },
            "isNSFW": {
              "type": "boolean",
              "description": "Whether the image contains NSFW content."
            },
            "isBDSM": {
              "type": "boolean",
              "description": "Whether the image contains BDSM elements."
            },
            "isUncensored": {
              "type": "boolean",
              "description": "Whether the image depicts uncensored genitalia."
            },
            "sourceCharacterName": {
              "type": "string",
              "description": "The exact name of the source character: {{源角色名称}}."
            },
            "hasPhysicalContact": {
              "type": "boolean",
              "description": "Whether the source character has significant physical contact (strictly BEYOND simple hand-holding) with other characters."
            },
            "involvedCharacters": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "[Reasoning] List names of characters having significant contact (excluding hand-holding) with the source character. Empty if none."
            },
            "interaction": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "A single, pure English action tag describing the interaction. Use ['none'] if no interaction.",
              "minItems": 1,
              "maxItems": 1
            }
          },
          "required": [
            "time",
            "locationAndBackground",
            "isNSFW",
            "isBDSM",
            "isUncensored",
            "sourceCharacterName",
            "hasPhysicalContact",
            "involvedCharacters",
            "interaction"
          ],
          "propertyOrdering": [
            "time",
            "locationAndBackground",
            "isNSFW",
            "isBDSM",
            "isUncensored",
            "sourceCharacterName",
            "hasPhysicalContact",
            "involvedCharacters",
            "interaction"
          ]
        },
        "characters": {
          "type": "array",
          "description": "List of characters appearing in the frame.",
          "items": {
            "type": "object",
            "properties": {
              "characterName": {
                "type": "string",
                "description": "Character's Chinese name."
              },
              "subjectType": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "['1girl'] or ['1boy'].",
                "minItems": 1,
                "maxItems": 1
              },
              "hairstyle": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Hairstyle tags, without color information."
              },
              "clothing": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Visible clothing tags."
              },
              "props": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Props being used."
              },
              "expression": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "The most primary facial expression tag.",
                "minItems": 1,
                "maxItems": 1
              },
              "specialStatus": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Dynamic physiological states.",
                "minItems": 0,
                "maxItems": 3
              },
              "pose": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Physical pose tags.",
                "minItems": 0,
                "maxItems": 3
              },
              "action": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "The most primary individual action tag.",
                "minItems": 1,
                "maxItems": 1
              },
              "interactionRole": {
                "type": "string",
                "enum": [
                  "initiator",
                  "receiver",
                  "mutual",
                  "none"
                ],
                "description": "The character's role in the global interaction."
              }
            },
            "required": [
              "characterName",
              "subjectType",
              "hairstyle",
              "clothing",
              "props",
              "expression",
              "specialStatus",
              "pose",
              "action",
              "interactionRole"
            ],
            "propertyOrdering": [
              "characterName",
              "subjectType",
              "hairstyle",
              "clothing",
              "props",
              "expression",
              "specialStatus",
              "pose",
              "action",
              "interactionRole"
            ]
          }
        }
      },
      "required": [
        "global",
        "characters"
      ],
      "propertyOrdering": [
        "global",
        "characters"
      ]
    },
    "test": {
      "type": "object",
      "description": "[Module 2: Testing]",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string"
              },
              "solution": {
                "type": "string"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "data",
    "test"
  ],
  "propertyOrdering": [
    "data",
    "test"
  ]
}

